import type { BankQuestion } from "@/lib/bank";

/** Rivers of India (Geography): 134 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"geo-indian-rivers-1","question":"Which is the longest river flowing in India?","options":["Godavari","Ganga","Brahmaputra","Yamuna"],"answer":1,"explanation":"The Ganga flows about 2,525 km within India, the longest of any river in the country.","difficulty":"easy"},
  {"id":"geo-indian-rivers-2","question":"The Ganga originates from the:","options":["Yamunotri glacier","Gangotri glacier","Mansarovar lake","Amarkantak plateau"],"answer":1,"explanation":"The Bhagirathi rises at Gaumukh, Gangotri glacier, and becomes the Ganga after meeting the Alaknanda at Devprayag.","difficulty":"easy"},
  {"id":"geo-indian-rivers-3","question":"Which river flows through Delhi?","options":["Ganga","Yamuna","Sutlej","Chambal"],"answer":1,"explanation":"The Yamuna, the largest tributary of the Ganga, flows through Delhi.","difficulty":"easy"},
  {"id":"geo-indian-rivers-4","question":"Which of these rivers flows westward into the Arabian Sea?","options":["Godavari","Krishna","Narmada","Mahanadi"],"answer":2,"explanation":"The Narmada flows west through a rift valley into the Arabian Sea; the others drain into the Bay of Bengal.","difficulty":"moderate"},
  {"id":"geo-indian-rivers-5","question":"Which river is known as the “Dakshin Ganga”?","options":["Kaveri","Godavari","Krishna","Tungabhadra"],"answer":1,"explanation":"The Godavari, the longest peninsular river, is called the Dakshin Ganga.","difficulty":"moderate"},
  {"id":"geo-indian-rivers-6","question":"The Narmada originates from the:","options":["Amarkantak plateau","Trimbakeshwar hills","Mahabaleshwar","Gangotri glacier"],"answer":0,"explanation":"The Narmada rises at Amarkantak in Madhya Pradesh.","difficulty":"moderate"},
  {"id":"geo-indian-rivers-7","question":"The Brahmaputra is known by which name in Tibet?","options":["Tsangpo","Dihang","Jamuna","Lohit"],"answer":0,"explanation":"It is the Tsangpo in Tibet, the Dihang in Arunachal Pradesh and the Jamuna in Bangladesh.","difficulty":"hard"},
  {"id":"geo-indian-rivers-8","question":"Hirakud Dam is built on which river?","options":["Godavari","Mahanadi","Sutlej","Krishna"],"answer":1,"explanation":"Hirakud Dam, in Odisha, is on the Mahanadi.","difficulty":"hard"},
  {"id":"geo-indian-rivers-9","question":"Bhakra Nangal Dam is built on which river?","options":["Beas","Ravi","Sutlej","Chenab"],"answer":2,"explanation":"Bhakra Dam, on the Sutlej in Himachal Pradesh, is one of the highest gravity dams in the world.","difficulty":"hard"},
  {"id":"geo-indian-rivers-10","question":"Which river is known as the “Sorrow of Bihar”?","options":["Gandak","Kosi","Son","Ghaghara"],"answer":1,"explanation":"The Kosi frequently changes course and floods north Bihar.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-11","question":"The Sardar Sarovar Dam is built on which river?","options":["Tapi","Narmada","Mahi","Sabarmati"],"answer":1,"explanation":"Sardar Sarovar, in Gujarat, is on the Narmada.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-12","question":"Which of these rivers does NOT originate in India?","options":["Godavari","Krishna","Brahmaputra","Mahanadi"],"answer":2,"explanation":"The Brahmaputra rises near Mansarovar in Tibet; the other three are peninsular rivers rising in India.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-13","question":"The longest river flowing entirely within India is the:","options":["Ganga","Godavari","Krishna","Narmada"],"answer":1,"explanation":"The Godavari (about 1,465 km) is the longest river wholly within India; the Ganga is longer overall but partly in Bangladesh.","difficulty":"easy","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-indian-rivers-14","question":"Which river forms the Jog (Gersoppa) Falls?","options":["Kaveri","Sharavathi","Periyar","Tungabhadra"],"answer":1,"explanation":"The Sharavathi river in Karnataka plunges at Jog Falls.","difficulty":"moderate","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-indian-rivers-15","question":"The Brahmaputra is known in Tibet as the:","options":["Dihang","Tsangpo","Jamuna","Lohit"],"answer":1,"explanation":"It rises as the Tsangpo in Tibet, enters India as the Dihang/Siang, and is the Jamuna in Bangladesh.","difficulty":"moderate","source":"SSC CGL · RRB NTPC"},
  {"id":"geo-indian-rivers-16","question":"Which of these rivers flows westward into the Arabian Sea through a rift valley?","options":["Mahanadi","Krishna","Narmada","Godavari"],"answer":2,"explanation":"The Narmada and Tapi flow west through rift valleys; the others drain east into the Bay of Bengal.","difficulty":"hard","source":"SSC CGL · UPSC Prelims"},
  {"id":"geo-indian-rivers-17","question":"The Bhakra Nangal dam is built on which river?","options":["Beas","Ravi","Sutlej","Chenab"],"answer":2,"explanation":"Bhakra Nangal, one of India’s highest gravity dams, stands on the Sutlej in Himachal Pradesh/Punjab.","difficulty":"hard","source":"SSC CGL · SSC CHSL"},
  {"id":"geo-indian-rivers-18","question":"The Indus Waters Treaty (1960) gives India unrestricted use of which three rivers?","options":["Indus, Jhelum, Chenab","Ravi, Beas, Sutlej","Jhelum, Ravi, Beas","Indus, Chenab, Sutlej"],"answer":1,"explanation":"The eastern rivers (Ravi, Beas, Sutlej) went to India; the western ones (Indus, Jhelum, Chenab) to Pakistan.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-19","question":"Which of these is NOT part of the Ganga river system?","options":["Chambal","Betwa","Son","Mahanadi"],"answer":3,"explanation":"Chambal and Betwa join the Yamuna, the Son joins the Ganga. The Mahanadi drains independently into the Bay of Bengal.","difficulty":"hard"},
  {"id":"geo-indian-rivers-20","question":"Which river rises at Amarkantak and flows westward into the Arabian Sea?","options":["Narmada","Son","Mahanadi","Tapi"],"answer":0,"explanation":"The Narmada rises at Amarkantak and flows west through a rift valley; the Tapi rises near Multai.","difficulty":"hard"},
  {"id":"geo-indian-rivers-21","question":"Arrange these east-flowing rivers from north to south:","options":["Mahanadi, Godavari, Krishna, Kaveri","Godavari, Mahanadi, Krishna, Kaveri","Mahanadi, Krishna, Godavari, Kaveri","Godavari, Krishna, Mahanadi, Kaveri"],"answer":0,"explanation":"Mahanadi (Odisha), Godavari (Andhra/Telangana), Krishna, then Kaveri (Tamil Nadu).","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-22","question":"The Tehri dam stands near the confluence of:","options":["Alaknanda and Bhagirathi","Bhagirathi and Bhilangana","Yamuna and Tons","Ganga and Ramganga"],"answer":1,"explanation":"Tehri dam is on the Bhagirathi, near its confluence with the Bhilangana. Alaknanda and Bhagirathi meet at Devprayag.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-23","question":"How many of these statements are correct? I. The Godavari is called the “Dakshin Ganga”. II. The Krishna rises near Mahabaleshwar. III. The Kaveri rises at Talakaveri in the Brahmagiri hills. IV. The Mahanadi rises in the Western Ghats.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Mahanadi rises near Sihawa in Chhattisgarh.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-24","question":"How many of these statements are correct? I. The Indus rises in Tibet near Lake Mansarovar. II. The Sutlej enters India through the Shipki La pass. III. The Chenab is formed by the Chandra and the Bhaga.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three are correct.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-25","question":"How many of these statements are correct? I. The Narmada flows through a rift valley. II. The Tapi rises in the Satpura range near Multai. III. The Mahi crosses the Tropic of Cancer twice.","options":["Only one","Only two","All three","None"],"answer":2,"explanation":"All three. The Narmada and Tapi flow west through rift valleys; the Mahi loops across the Tropic of Cancer twice before reaching the Gulf of Khambhat.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-26","question":"Arrange these tributaries of the Indus from north to south: 1. Jhelum 2. Ravi 3. Chenab 4. Sutlej","options":["1-3-2-4","1-2-3-4","3-1-2-4","1-3-4-2"],"answer":0,"explanation":"From north to south: Jhelum, Chenab, Ravi, Beas, Sutlej.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-27","question":"The Ganga is formed by the confluence of the Bhagirathi and the Alaknanda at:","options":["Devprayag","Rudraprayag","Karnaprayag","Vishnuprayag"],"answer":0,"explanation":"At Devprayag. Rudraprayag joins the Mandakini, Karnaprayag the Pindar and Vishnuprayag the Dhauliganga with the Alaknanda.","difficulty":"very-hard"},
  {"id":"geo-indian-rivers-28","question":"Which pair of river and tributary is NOT correctly matched?","options":["Krishna – Bhima","Godavari – Manjra","Kaveri – Kabini","Mahanadi – Indravati"],"answer":3,"explanation":"The Indravati joins the Godavari. The main tributaries of the Mahanadi are the Seonath, Ib, Tel and Jonk.","difficulty":"very-hard","source":"UPSC Prelims · SSC CGL"},
  {"id":"geo-indian-rivers-29","question":"How many of these statements are correct? I. The Luni ends in the Rann of Kutch. II. The Damodar is a tributary of the Hugli. III. The Brahmaputra is called the Dihang in Arunachal Pradesh. IV. The Sabarmati flows into the Gulf of Kutch.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"I, II and III are correct. The Sabarmati, like the Mahi and the Narmada, drains into the Gulf of Khambhat.","difficulty":"very-hard","source":"SSC CGL · UPSC Prelims"},
  {"id": "geo-indian-rivers-30", "question": "The Nagarjuna Sagar dam is built on the river:", "options": ["Godavari", "Krishna", "Kaveri", "Mahanadi"], "answer": 1, "explanation": "Nagarjuna Sagar, on the Krishna between Telangana and Andhra Pradesh, was one of the earliest large multipurpose projects of independent India. Srisailam is also on the Krishna.", "difficulty": "easy", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-indian-rivers-31", "question": "The Yamuna rises from the:", "options": ["Gangotri glacier", "Yamunotri glacier", "Satopanth glacier", "Siachen glacier"], "answer": 1, "explanation": "The Yamuna starts from the Yamunotri glacier on the Banderpunch range in Uttarakhand and joins the Ganga at Prayagraj (Allahabad).", "difficulty": "easy", "source": "SSC CHSL · UPSSSC PET"},
  {"id": "geo-indian-rivers-32", "question": "Lucknow, the capital of Uttar Pradesh, stands on the bank of the river:", "options": ["Ganga", "Gomti", "Ghaghara", "Sarayu"], "answer": 1, "explanation": "The Gomti, a sluggish left-bank tributary of the Ganga rising from Gomat Taal near Pilibhit, flows through Lucknow and Jaunpur.", "difficulty": "easy", "source": "SSC CGL · UPSSSC PET"},
  {"id": "geo-indian-rivers-33", "question": "The Chambal, a tributary of the Yamuna, rises from the:", "options": ["Janapav hills near Mhow (Madhya Pradesh)", "Amarkantak plateau", "Aravalli hills near Udaipur", "Vindhya range near Bhopal"], "answer": 0, "explanation": "The Chambal rises at Janapav in the Vindhya range near Mhow, flows through Rajasthan (Gandhi Sagar, Rana Pratap Sagar and Kota barrage) and joins the Yamuna in Uttar Pradesh; it is famous for its ravines.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "geo-indian-rivers-34", "question": "Which peninsular river rises at Amarkantak and flows NORTH to join the Ganga as a right-bank tributary near Patna?", "options": ["Narmada", "Son", "Betwa", "Ken"], "answer": 1, "explanation": "The Son rises on the Amarkantak plateau, like the Narmada, but flows north-east and joins the Ganga near Danapur; the Betwa and Ken are tributaries of the Yamuna.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "geo-indian-rivers-35", "question": "The Mettur dam, one of the oldest large dams in India (1934), is built on the:", "options": ["Krishna", "Periyar", "Kaveri", "Vaigai"], "answer": 2, "explanation": "Mettur dam in Salem district, Tamil Nadu, impounds the Kaveri as the Stanley reservoir and irrigates the Kaveri delta.", "difficulty": "moderate", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-indian-rivers-36", "question": "The Salal and Baglihar hydroelectric projects in Jammu and Kashmir are on the river:", "options": ["Jhelum", "Chenab", "Ravi", "Indus"], "answer": 1, "explanation": "Both projects are on the Chenab; the Kishanganga and Uri projects are on the Jhelum system and the Ranjit Sagar (Thein) dam is on the Ravi.", "difficulty": "moderate", "source": "SSC CGL · UPSC Prelims"},
  {"id": "geo-indian-rivers-37", "question": "The Tungabhadra, formed by the union of the Tunga and the Bhadra, is a tributary of the:", "options": ["Godavari", "Kaveri", "Krishna", "Mahanadi"], "answer": 2, "explanation": "The Tungabhadra rises in the Western Ghats of Karnataka, flows past Hampi and joins the Krishna in Andhra Pradesh; the Bhima is the other major Krishna tributary.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL"},
  {"id": "geo-indian-rivers-38", "question": "The Indus enters Indian territory in Ladakh and flows between which two ranges?", "options": ["Zanskar and Ladakh ranges", "Great Himalaya and Pir Panjal", "Karakoram and Kunlun", "Shiwalik and Dhauladhar"], "answer": 0, "explanation": "After entering Ladakh near Demchok, the Indus flows north-west past Leh in the trough between the Ladakh range to its north and the Zanskar range to its south.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-39", "question": "Which Himalayan tributary of the Ganga is known as the Karnali in Nepal?", "options": ["Gandak", "Ghaghara", "Kosi", "Ramganga"], "answer": 1, "explanation": "The Ghaghara (Karnali in Nepal) rises near Mansarovar and joins the Ganga at Chhapra; the Gandak is called the Narayani in Nepal.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-40", "question": "The Brahmaputra takes that name in Assam after the union, near Sadiya, of the Dihang with the:", "options": ["Subansiri and Manas", "Dibang and Lohit", "Teesta and Torsa", "Dhansiri and Kopili"], "answer": 1, "explanation": "The Dihang (Siang) meets the Dibang and the Lohit near Sadiya and the combined stream is called the Brahmaputra; the Subansiri and Manas join further downstream.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-41", "question": "The Shivasamudram falls, where one of Asia’s earliest hydroelectric stations was set up in 1902, are on the:", "options": ["Krishna", "Kaveri", "Sharavathi", "Godavari"], "answer": 1, "explanation": "The Kaveri drops over the Shivasamudram falls in Karnataka; the Jog falls are on the Sharavathi and the Hogenakkal falls, also on the Kaveri, lie downstream in Tamil Nadu.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "geo-indian-rivers-42", "question": "Which of these is NOT a tributary of the Godavari?", "options": ["Indravati", "Manjra", "Pranhita", "Bhima"], "answer": 3, "explanation": "The Bhima is a tributary of the Krishna. The Godavari’s tributaries include the Pranhita (formed by the Wardha, Wainganga and Penganga), Indravati, Manjra, Purna and Sabari.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-43", "question": "Hyderabad is situated on the banks of the river:", "options": ["Krishna", "Musi", "Manjra", "Tungabhadra"], "answer": 1, "explanation": "The Musi, a tributary of the Krishna, flows through Hyderabad; the Osman Sagar and Himayat Sagar reservoirs were built on it after the 1908 flood.", "difficulty": "hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-indian-rivers-44", "question": "The Mahanadi rises at:", "options": ["Amarkantak, Madhya Pradesh", "Sihawa near Dhamtari, Chhattisgarh", "Nasik, Maharashtra", "Mahabaleshwar, Maharashtra"], "answer": 1, "explanation": "The Mahanadi rises near Sihawa in Dhamtari district of Chhattisgarh and flows through Odisha to the Bay of Bengal; the Hirakud dam stands on it near Sambalpur.", "difficulty": "hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "geo-indian-rivers-45", "question": "The Beas joins the Sutlej at:", "options": ["Harike (Punjab)", "Ropar (Punjab)", "Ferozepur (Punjab)", "Nangal (Punjab)"], "answer": 0, "explanation": "The Beas, which flows entirely within India, meets the Sutlej at Harike, where a barrage feeds the Indira Gandhi (Rajasthan) canal; Harike wetland is a Ramsar site.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-46", "question": "The longest river of Kerala is the:", "options": ["Bharathapuzha", "Periyar", "Pamba", "Chaliyar"], "answer": 1, "explanation": "The Periyar (244 km) is Kerala’s longest river; the Bharathapuzha (Ponnani) is the second longest. The Pamba is the river of Sabarimala.", "difficulty": "hard", "source": "SSC CGL · State PSC"},
  {"id": "geo-indian-rivers-47", "question": "Which river rises on the Chhota Nagpur plateau near Ranchi and flows directly into the Bay of Bengal without joining the Ganga?", "options": ["Damodar", "Son", "Subarnarekha", "Chambal"], "answer": 2, "explanation": "The Subarnarekha flows through Jharkhand, West Bengal and Odisha to the Bay of Bengal; the Damodar joins the Hugli and the Son joins the Ganga.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-48", "question": "How many of these statements about the Ganga are correct? I. Its length is about 2,525 km. II. The Bhagirathi is regarded as the source stream although the Alaknanda is the larger of the two. III. The Farakka barrage diverts Ganga water into the Hugli. IV. In Bangladesh the Ganga is called the Padma and joins the Brahmaputra (Jamuna).", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The combined Padma–Jamuna later meets the Meghna before entering the Bay of Bengal.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-49", "question": "Arrange these left-bank tributaries of the Ganga from west to east: 1. Kosi 2. Gomti 3. Ghaghara 4. Gandak", "options": ["2, 3, 4, 1", "3, 2, 4, 1", "2, 4, 3, 1", "2, 3, 1, 4"], "answer": 0, "explanation": "Gomti (joins at Ghazipur), Ghaghara (at Chhapra), Gandak (at Hajipur, opposite Patna) and Kosi (near Kursela in Bihar).", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-50", "question": "Which pair of dam and river is NOT correctly matched?", "options": ["Tehri – Bhagirathi", "Koyna – Koyna", "Ukai – Tapi", "Gandhi Sagar – Betwa"], "answer": 3, "explanation": "Gandhi Sagar (Madhya Pradesh) is on the Chambal; the Betwa has the Rajghat (Matatila) dam.", "difficulty": "very-hard", "source": "SSC CGL · UPSC Prelims"},
  {"id": "geo-indian-rivers-51", "question": "Assertion (A): The Kosi frequently shifts its course across north Bihar. Reason (R): It carries a very heavy sediment load from the Himalaya and deposits it on the plains, raising its bed.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Bed aggradation forces the river to spill and shift, which is why it has moved westward by over 100 km in two centuries and earned the name “Sorrow of Bihar”.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-indian-rivers-52", "question": "How many of these statements about west-flowing rivers are correct? I. The Narmada forms the Dhuandhar falls at Bhedaghat near Jabalpur. II. The Tapi enters the Gulf of Khambhat near Surat. III. The Sharavathi falls into the Bay of Bengal. IV. The Mahi rises in Madhya Pradesh and drains into the Gulf of Khambhat.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The Sharavathi, famous for the Jog falls, is a west-flowing river of Karnataka that enters the Arabian Sea at Honnavar.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-53", "question": "How many of these statements about the Brahmaputra are correct? I. It rises from the Chemayungdung glacier near Mansarovar. II. In Bangladesh it is called the Jamuna. III. It takes a hairpin bend around Namcha Barwa before entering India. IV. Its length within India is greater than its length within Tibet.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. Most of the river’s length (about 1,600 km) is in Tibet; its course within India is under 1,000 km.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-indian-rivers-54", "question": "Which of these rivers does NOT form a delta at its mouth?", "options": ["Mahanadi", "Godavari", "Narmada", "Krishna"], "answer": 2, "explanation": "The Narmada, like the Tapi, forms an estuary because it flows through a rift valley with a steep gradient and little sediment, and the Arabian Sea coast has strong tidal action; the east-flowing rivers form deltas.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-55", "question": "Which pair of city and river is NOT correctly matched?", "options": ["Surat – Tapi", "Nashik – Godavari", "Vijayawada – Krishna", "Jabalpur – Tapi"], "answer": 3, "explanation": "Jabalpur stands on the Narmada, near the marble rocks of Bhedaghat; the Tapi flows through Burhanpur and Surat.", "difficulty": "very-hard", "source": "SSC CGL · RRB NTPC"},
  {"id": "geo-indian-rivers-56", "question": "Arrange these dams in the order of their completion or commissioning: 1. Tehri 2. Hirakud 3. Sardar Sarovar 4. Bhakra", "options": ["2, 4, 1, 3", "4, 2, 1, 3", "2, 4, 3, 1", "2, 1, 4, 3"], "answer": 0, "explanation": "Hirakud (1957), Bhakra (1963), Tehri (2006) and Sardar Sarovar (dedicated to the nation in 2017).", "difficulty": "very-hard", "source": "SSC CGL · State PSC"},
  {"id": "geo-indian-rivers-57", "question": "How many of these statements about the Indus system are correct? I. The Indus is about 2,880 km long. II. The Jhelum rises at Verinag in the Kashmir valley. III. The Ravi rises near the Rohtang pass in the Kullu hills. IV. The Beas rises at Beas Kund near the Rohtang pass and flows entirely within India.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The Ravi and Beas both rise near Rohtang, on opposite sides of the Pir Panjal; the Beas is the only Indus tributary that never leaves India.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-58", "question": "Assertion (A): East-flowing peninsular rivers such as the Godavari form deltas, while the Narmada and Tapi form estuaries. Reason (R): The west-flowing rivers run through rift valleys with steep gradients, carry little sediment, and meet a coast with strong tidal action.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Delta formation needs abundant sediment and a gentle, shallow coast; the east-flowing rivers have both, while the Narmada and Tapi lack sediment and face a submerged, tidal western coast.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-indian-rivers-59", "question": "How many of these statements about inter-state river disputes are correct? I. The Kaveri dispute involves Karnataka, Tamil Nadu, Kerala and Puducherry. II. The Krishna water dispute involves Maharashtra, Karnataka, Andhra Pradesh and Telangana. III. The Mahadayi (Mandovi) dispute is among Goa, Karnataka and Maharashtra. IV. The Sutlej–Yamuna Link canal dispute is between Punjab and Rajasthan.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The SYL canal dispute is between Punjab and Haryana, over Haryana’s share of Ravi–Beas water.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-60", "question": "Kolkata stands on the bank of the river:", "options": ["Damodar", "Hugli", "Rupnarayan", "Padma"], "answer": 1, "explanation": "Kolkata lies on the east bank of the Hugli (Bhagirathi–Hugli), a distributary of the Ganga. The Padma is the Ganga’s name in Bangladesh.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-61", "question": "Srinagar, the summer capital of Jammu and Kashmir, is situated on the river:", "options": ["Chenab", "Jhelum", "Indus", "Tawi"], "answer": 1, "explanation": "The Jhelum flows through Srinagar and the Kashmir valley. Jammu stands on the Tawi.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-62", "question": "The city of Pune lies at the confluence of the rivers:", "options": ["Mula and Mutha", "Bhima and Nira", "Krishna and Koyna", "Godavari and Pravara"], "answer": 0, "explanation": "The Mula and Mutha meet at Pune; the combined Mula-Mutha later joins the Bhima, a tributary of the Krishna.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-63", "question": "The Kishanganga, called the Neelum in Pakistan-administered Kashmir, is a tributary of the:", "options": ["Chenab", "Ravi", "Indus directly", "Jhelum"], "answer": 3, "explanation": "The Kishanganga joins the Jhelum near Muzaffarabad. India’s Kishanganga hydroelectric project diverts its water to the Wular lake area.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-64", "question": "The Mahatma Gandhi Setu, one of India’s longest river bridges, spans the Ganga at:", "options": ["Varanasi", "Bhagalpur", "Patna", "Prayagraj"], "answer": 2, "explanation": "The Gandhi Setu links Patna with Hajipur across the Ganga. Bhagalpur has the Vikramshila Setu.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-65", "question": "The Narmada flows westward through a rift valley lying between:", "options": ["The Vindhya and Satpura ranges", "The Satpura and Ajanta ranges", "The Aravalli and Vindhya ranges", "The Maikal and Mahadeo hills"], "answer": 0, "explanation": "The Narmada flows between the Vindhyas to the north and the Satpuras to the south. The Tapi flows in a parallel trough south of the Satpuras.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-66", "question": "Which river was known as the “Sorrow of Bengal” because of its devastating floods before multipurpose dams were built on it?", "options": ["Kosi", "Hugli", "Damodar", "Teesta"], "answer": 2, "explanation": "The Damodar flooded Bengal frequently until the Damodar Valley Corporation built dams on it. The Kosi is the Sorrow of Bihar.", "difficulty": "moderate", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-67", "question": "The Bhima, a major tributary of the Krishna, rises at:", "options": ["Mahabaleshwar", "Trimbakeshwar", "Bhimashankar in the Western Ghats", "Nasik"], "answer": 2, "explanation": "The Bhima rises at Bhimashankar (Pune district) and joins the Krishna near Raichur. The Krishna rises at Mahabaleshwar and the Godavari at Trimbakeshwar near Nasik.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-68", "question": "The Gandak, a left-bank tributary of the Ganga, is known in Nepal as the:", "options": ["Karnali", "Sapt Kosi", "Narayani", "Bagmati"], "answer": 2, "explanation": "In Nepal the Gandak is called the Narayani (Sapta Gandaki); it joins the Ganga near Patna. The Karnali becomes the Ghaghara and the Sapt Kosi the Kosi.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-69", "question": "The historic town of Orchha in Madhya Pradesh lies on the bank of the:", "options": ["Betwa", "Ken", "Sindh", "Dhasan"], "answer": 0, "explanation": "Orchha, the old Bundela capital, is on the Betwa, a tributary of the Yamuna. The Ken flows past Panna and through Khajuraho’s region.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-70", "question": "The Damodar Valley Corporation (1948), India’s first multipurpose river valley project, was modelled on the:", "options": ["Hoover Dam project", "Tennessee Valley Authority of the USA", "Aswan High Dam project", "Snowy Mountains Scheme of Australia"], "answer": 1, "explanation": "The DVC was modelled on the Tennessee Valley Authority, an integrated river-basin agency set up in the USA in 1933.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-71", "question": "The temple city of Madurai stands on the bank of the river:", "options": ["Tamraparni", "Kaveri", "Palar", "Vaigai"], "answer": 3, "explanation": "Madurai lies on the Vaigai, which flows into the Palk Bay. The Tamraparni flows past Tirunelveli.", "difficulty": "hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-72", "question": "The Ken–Betwa link project, the first project under India’s National Perspective Plan for interlinking rivers, transfers surplus water from the Ken to the Betwa. Both rivers are tributaries of the:", "options": ["Ganga directly", "Son", "Chambal", "Yamuna"], "answer": 3, "explanation": "The Ken and the Betwa are right-bank tributaries of the Yamuna in Bundelkhand. The project includes the Daudhan dam in Panna district.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-73", "question": "In April 2025, following the Pahalgam terror attack, India announced that it was holding in abeyance the:", "options": ["Ganga Water Treaty with Bangladesh", "Indus Waters Treaty with Pakistan", "Mahakali Treaty with Nepal", "Kosi Agreement with Nepal"], "answer": 1, "explanation": "India placed the 1960 Indus Waters Treaty, brokered by the World Bank, in abeyance. Under it India controls the eastern rivers (Ravi, Beas, Sutlej) and Pakistan the western rivers (Indus, Jhelum, Chenab).", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-74", "question": "Match the river with its source: A. Godavari B. Penna (Pennar) C. Son D. Chambal. 1. Janapav hills near Mhow 2. Amarkantak 3. Nandi hills, Karnataka 4. Trimbakeshwar", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-3, B-4, C-2, D-1", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "The Godavari rises at Trimbakeshwar (Nasik), the Penna in the Nandi hills (Chikkaballapur), the Son at Amarkantak and the Chambal in the Janapav hills near Mhow.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-75", "question": "Arrange these confluences on the Alaknanda from upstream to downstream: 1. Rudraprayag 2. Vishnuprayag 3. Karnaprayag 4. Nandprayag", "options": ["2, 3, 4, 1", "4, 2, 3, 1", "2, 4, 1, 3", "2, 4, 3, 1"], "answer": 3, "explanation": "Vishnuprayag (Dhauliganga), Nandprayag (Nandakini), Karnaprayag (Pindar), Rudraprayag (Mandakini); then Devprayag, where the Bhagirathi joins and the Ganga begins.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-76", "question": "Assertion (A): The Himalayan rivers of the Ganga system are perennial. Reason (R): They are fed both by melting snow and glaciers and by monsoon rainfall.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Snowmelt keeps them flowing in the dry summer months, and the monsoon swells them in the rainy season, unlike the rain-fed peninsular rivers.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-77", "question": "How many of these statements about the tributaries of the Brahmaputra are correct? I. The Subansiri joins it from the north bank. II. The Manas joins it from the north bank. III. The Dhansiri joins it from the south bank. IV. The Teesta joins it within Indian territory.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. IV is wrong: the Teesta flows from Sikkim through West Bengal into Bangladesh and joins the Brahmaputra (Jamuna) there.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-78", "question": "Arrange these water agreements in chronological order: 1. Ganga Water Treaty with Bangladesh 2. Indus Waters Treaty 3. Mahakali Treaty with Nepal 4. Kosi Agreement with Nepal", "options": ["4, 2, 3, 1", "2, 4, 3, 1", "4, 2, 1, 3", "4, 3, 2, 1"], "answer": 0, "explanation": "Kosi Agreement: 1954. Indus Waters Treaty: 1960. Mahakali Treaty: February 1996. Ganga Water Treaty: December 1996.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-79", "question": "Which of these rivers is a RIGHT-bank tributary of the Indus?", "options": ["Jhelum", "Chenab", "Kabul", "Sutlej"], "answer": 2, "explanation": "The Kabul joins the Indus from the right (west) near Attock, as do the Kurram, Tochi and Gomal. The Jhelum, Chenab, Ravi, Beas and Sutlej are left-bank tributaries joining via the Panjnad.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-80", "question": "Match the waterfall with the river: A. Dudhsagar B. Hogenakkal C. Chitrakote D. Athirappilly. 1. Chalakudy 2. Indravati 3. Kaveri 4. Mandovi", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1"], "answer": 3, "explanation": "Dudhsagar (Goa–Karnataka border) is on the Mandovi; Hogenakkal (Tamil Nadu) on the Kaveri; Chitrakote (Chhattisgarh) on the Indravati; Athirappilly (Kerala) on the Chalakudy.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-81", "question": "How many of these dams are correctly matched with their river? I. Tehri – Bhagirathi II. Indira Sagar – Narmada III. Ukai – Mahi IV. Koyna – Koyna, in Maharashtra", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. III is wrong: the Ukai dam is on the Tapi in Gujarat; the Mahi has the Kadana and Mahi Bajaj Sagar dams.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-82", "question": "Assertion (A): The Chambal valley is known for its deep ravines (badlands). Reason (R): Intense gully erosion has cut deeply into the soft alluvial soils along the river.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A. Run-off from heavy seasonal rain has dissected the soft alluvium along the Chambal into a maze of ravines.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-83", "question": "How many of these statements about the peninsular rivers are correct? I. The Kaveri has a relatively steady flow because its basin receives rain from both the south-west and north-east monsoons. II. The Krishna is the second-largest east-flowing peninsular river. III. The Mahanadi forms its delta in Odisha. IV. The Godavari has the largest basin among peninsular rivers.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The upper Kaveri catchment in Karnataka gets the south-west monsoon and the lower basin in Tamil Nadu the north-east monsoon, so its flow fluctuates less than other peninsular rivers.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-84", "question": "Arrange the mouths of these west-flowing rivers from north to south: 1. Tapi 2. Mahi 3. Narmada 4. Sabarmati", "options": ["4, 2, 3, 1", "2, 4, 3, 1", "4, 3, 2, 1", "4, 2, 1, 3"], "answer": 0, "explanation": "The Sabarmati and the Mahi enter the head of the Gulf of Khambhat, the Sabarmati further north; the Narmada reaches the sea near Bharuch and the Tapi near Surat.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-85", "question": "Ahmedabad, the largest city of Gujarat, stands on the bank of the river:", "options": ["Mahi", "Sabarmati", "Tapi", "Narmada"], "answer": 1, "explanation": "Ahmedabad lies on the Sabarmati, which rises in the Aravalli and flows into the Gulf of Khambhat. Surat is on the Tapi and Vadodara near the Vishwamitri.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-86", "question": "Which animal was declared India's National Aquatic Animal in 2009?", "options": ["Gharial", "Ganges river dolphin", "Olive ridley turtle", "Dugong"], "answer": 1, "explanation": "The Ganges river dolphin, a blind river dolphin found in the Ganga–Brahmaputra system, was declared the National Aquatic Animal in 2009. The gharial is protected in the Chambal sanctuary.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-87", "question": "The city of Ujjain, where the Simhastha Kumbh is held, stands on the river:", "options": ["Chambal", "Shipra", "Betwa", "Narmada"], "answer": 1, "explanation": "Ujjain is on the Shipra (Kshipra), a tributary of the Chambal. Nashik (Godavari), Haridwar and Prayagraj (Ganga) are the other Kumbh cities.", "difficulty": "easy", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-88", "question": "Ayodhya stands on the bank of the Saryu, which is the name given to the lower course of the:", "options": ["Ghaghara", "Gomti", "Gandak", "Ramganga"], "answer": 0, "explanation": "The Ghaghara (Karnali in Nepal) is called the Saryu near Ayodhya. It joins the Ganga near Chhapra in Bihar.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-89", "question": "The largest tributary of the Yamuna in the Himalayan region, which joins it near Kalsi in Uttarakhand, is the:", "options": ["Hindon", "Giri", "Chambal", "Tons"], "answer": 3, "explanation": "The Tons, rising near Bandarpunch, is the Yamuna's largest Himalayan tributary. The Chambal is the largest tributary overall, joining from the plateau side much further down.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-90", "question": "The Govind Ballabh Pant Sagar reservoir in Sonbhadra (Uttar Pradesh) is formed by a dam on the:", "options": ["Betwa", "Ken", "Gomti", "Rihand"], "answer": 3, "explanation": "The Rihand dam stands on the Rihand river, a tributary of the Son, and its reservoir is one of India's largest artificial lakes. It powers the Singrauli energy belt.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-91", "question": "The Ukai dam, Gujarat's largest reservoir, is built on the:", "options": ["Tapi", "Mahi", "Sabarmati", "Narmada"], "answer": 0, "explanation": "Ukai (with the Kakrapar weir downstream) is on the Tapi. The Kadana dam is on the Mahi and Sardar Sarovar on the Narmada.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-92", "question": "The Krishna Raja Sagar (KRS) dam near Mysuru, with the Brindavan gardens below it, is on the:", "options": ["Krishna", "Kaveri", "Tungabhadra", "Kabini"], "answer": 1, "explanation": "Despite its name, KRS is on the Kaveri, just below where the Hemavati and Lakshmana Tirtha join it. It was named after Krishnaraja Wadiyar IV, Maharaja of Mysore.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-93", "question": "Cuttack, the old capital of Odisha, stands at the head of the delta of the:", "options": ["Brahmani", "Baitarani", "Mahanadi", "Subarnarekha"], "answer": 2, "explanation": "Cuttack lies where the Mahanadi divides, between the Mahanadi and its branch the Kathajodi. The delta spreads out from here towards the coast.", "difficulty": "moderate", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-94", "question": "The Sutlej rises in Tibet from:", "options": ["Lake Mansarovar", "Chemayungdung glacier", "Rakas Tal (Langa Tso)", "Beas Kund"], "answer": 2, "explanation": "The Sutlej rises from Rakas Tal near Mansarovar and enters India at Shipki La. The Brahmaputra rises from the Chemayungdung glacier and the Beas from Beas Kund.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-95", "question": "The Bansagar dam, a joint project of Madhya Pradesh, Uttar Pradesh and Bihar, is on the:", "options": ["Ken", "Son", "Betwa", "Narmada"], "answer": 1, "explanation": "The Bansagar dam in Shahdol district, MP, is on the Son and supplies irrigation and power to all three States. The Ken–Betwa link joins two other Yamuna tributaries.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-96", "question": "The Polavaram multipurpose project, declared a national project, is being built on the:", "options": ["Krishna", "Penna", "Vamsadhara", "Godavari"], "answer": 3, "explanation": "Polavaram is on the Godavari in Andhra Pradesh. It is to transfer Godavari water to the Krishna basin through the Polavaram right canal.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-97", "question": "The Almatti dam (Lal Bahadur Shastri dam) in north Karnataka is on the:", "options": ["Krishna", "Tungabhadra", "Bhima", "Ghataprabha"], "answer": 0, "explanation": "Almatti is on the Krishna in Vijayapura–Bagalkot district, and the height of its reservoir has been a point in the Krishna water dispute. The Tungabhadra dam is at Hosapete.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-98", "question": "The Barak, which flows through Manipur, Mizoram and Assam (past Silchar), enters Bangladesh and divides into:", "options": ["The Padma and the Jamuna", "The Surma and the Kushiyara", "The Meghna and the Teesta", "The Karnaphuli and the Feni"], "answer": 1, "explanation": "The Barak splits into the Surma and the Kushiyara in Bangladesh, and these later form the Meghna. The Meghna joins the Padma before reaching the Bay of Bengal.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "geo-indian-rivers-99", "question": "The Ghaggar, a seasonal river that rises in the Shiwaliks and dies out in the Rajasthan desert, is known in Pakistan as the:", "options": ["Luni", "Sutlej", "Chenab", "Hakra"], "answer": 3, "explanation": "The Ghaggar–Hakra is a stream of inland drainage that ends in the sands near Hanumangarh. Many Harappan sites line its old bed, and some identify it with the Vedic Sarasvati.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-100", "question": "The Hundru falls near Ranchi are formed by the:", "options": ["Damodar", "Koel", "Subarnarekha", "Barakar"], "answer": 2, "explanation": "The Subarnarekha drops about 98 m at Hundru on the edge of the Ranchi plateau. The Damodar and Barakar flow east towards West Bengal.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "geo-indian-rivers-101", "question": "The Gokak falls in Belagavi district, Karnataka, are on the:", "options": ["Ghataprabha", "Malaprabha", "Sharavathi", "Tungabhadra"], "answer": 0, "explanation": "The Ghataprabha, a tributary of the Krishna, forms the Gokak falls. The Sharavathi forms the Jog falls.", "difficulty": "hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "geo-indian-rivers-102", "question": "The Shyok, which rises from the Rimo glacier near the Karakoram, joins the Indus near:", "options": ["Leh", "Attock", "Kargil", "Skardu"], "answer": 3, "explanation": "The Shyok runs through Ladakh and Baltistan and meets the Indus near Skardu. At Attock the Kabul river joins the Indus.", "difficulty": "hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-103", "question": "Match the drainage pattern with an example: A. Dendritic B. Radial C. Centripetal D. Trellis. 1. Rivers flowing out in all directions from the Amarkantak range 2. Rivers of the northern plains, branching like a tree 3. Streams draining into Loktak lake 4. Parallel streams with tributaries joining at right angles, as in old folded hills", "options": ["A-2, B-1, C-3, D-4", "A-1, B-2, C-3, D-4", "A-2, B-3, C-1, D-4", "A-2, B-1, C-4, D-3"], "answer": 0, "explanation": "Dendritic: tree-like, as in the Indo-Gangetic plain. Radial: from a central high point such as Amarkantak. Centripetal: streams draining into a basin, such as Loktak. Trellis: tributaries meeting the main stream at right angles in folded or structurally controlled country.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-104", "question": "Assertion (A): The Indus, the Sutlej and the Brahmaputra cut across the Himalaya through deep gorges. Reason (R): They are antecedent rivers, older than the Himalaya, which kept cutting down their beds as the mountains rose.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "These rivers kept to their old courses while the Himalaya slowly rose, so they carved gorges through the ranges, such as the Indus gorge near Gilgit and the Dihang gorge of the Brahmaputra.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-105", "question": "Match the National Waterway with its route: A. NW-1 B. NW-2 C. NW-3 D. NW-4. 1. Godavari and Krishna rivers with the Kakinada–Puducherry canals 2. West Coast Canal in Kerala 3. Brahmaputra from Dhubri to Sadiya 4. Ganga–Bhagirathi–Hooghly from Prayagraj to Haldia", "options": ["A-4, B-3, C-1, D-2", "A-3, B-4, C-2, D-1", "A-4, B-3, C-2, D-1", "A-4, B-2, C-3, D-1"], "answer": 2, "explanation": "NW-1 (Prayagraj–Haldia) is the longest. NW-2 is on the Brahmaputra, NW-3 is the West Coast Canal (Kottapuram–Kollam), and NW-4 links the Godavari and Krishna with the Kakinada–Puducherry canal system.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-106", "question": "How many of these statements about the Kaveri are correct? I. The Hemavati, Kabini, Bhavani and Amaravati are its tributaries. II. It forms the river islands of Srirangapatna and Srirangam. III. It reaches the Bay of Bengal in Tamil Nadu, its old mouth being at Poompuhar (Kaveripattinam). IV. It rises at Trimbakeshwar.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Kaveri rises at Talakaveri in the Brahmagiri hills of Kodagu. Trimbakeshwar near Nashik is the source of the Godavari.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-107", "question": "How many of these statements about the Chambal are correct? I. The Banas, Kali Sindh and Parbati are its tributaries. II. The Gandhi Sagar, Rana Pratap Sagar and Jawahar Sagar dams are on it. III. The National Chambal Sanctuary protects the gharial. IV. It joins the Yamuna in the Etawah region.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The Chambal flows north through Madhya Pradesh and Rajasthan, with the Kota barrage below the three dams, and then forms the MP–Rajasthan and MP–UP boundaries before joining the Yamuna.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-108", "question": "Arrange in chronological order: 1. Launch of the Ganga Action Plan 2. Launch of the Namami Gange programme 3. Ganga declared the National River 4. Setting up of the Damodar Valley Corporation", "options": ["1, 4, 3, 2", "4, 1, 3, 2", "4, 3, 1, 2", "4, 1, 2, 3"], "answer": 1, "explanation": "Damodar Valley Corporation 1948 → Ganga Action Plan 1986 → Ganga declared the National River 2008 → Namami Gange 2014.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-109", "question": "How many of these statements about west-flowing rivers are correct? I. The Mandovi and the Zuari flow through Goa. II. The Netravati enters the Arabian Sea at Mangaluru. III. The Periyar flows into the Bay of Bengal. IV. The Kali (Kalinadi) reaches the sea at Karwar.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and IV are correct. The Periyar, Kerala's longest river, flows west into the Arabian Sea near Kochi, past the Idukki dam.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-110", "question": "Which of these is NOT a tributary of the Mahanadi?", "options": ["Wardha", "Seonath", "Hasdeo", "Ib"], "answer": 0, "explanation": "The Seonath, Hasdeo, Mand, Ib and Tel feed the Mahanadi. The Wardha joins the Wainganga to form the Pranhita, which flows into the Godavari.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-111", "question": "Assertion (A): The Ganga–Brahmaputra delta is the largest delta in the world. Reason (R): The two rivers together bring down an enormous load of Himalayan sediment and deposit it at the head of the Bay of Bengal.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The Ganga, Brahmaputra and Meghna together carry one of the world's largest sediment loads. The delta they have built, with the Sundarbans mangroves on its sea face, is the world's largest.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-112", "question": "How many of these statements are correct? I. The Brahmani is formed by the union of the Koel and the Sankh near Rourkela. II. The Baitarani rises in the Gonasika hills of Keonjhar. III. The Bhitarkanika mangroves lie in the Brahmani–Baitarani delta. IV. The Baitarani is a tributary of the Mahanadi.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct. The Baitarani is an independent river that reaches the Bay of Bengal through its own delta, shared with the Brahmani.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSCs"},
  {"id": "geo-indian-rivers-113", "question": "Which of these cities is paired with the WRONG river?", "options": ["Vijayawada – Krishna", "Nashik – Godavari", "Surat – Tapi", "Ludhiana – Beas"], "answer": 3, "explanation": "Ludhiana stands near the Sutlej. Vijayawada has the Prakasam barrage on the Krishna, Nashik is on the upper Godavari, and Surat is near the mouth of the Tapi.", "difficulty": "very-hard", "source": "SSC CGL · SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-114", "question": "How many of these statements about the Ganga basin are correct? I. It is the largest river basin in India. II. Uttar Pradesh has the longest stretch of the Ganga among the States. III. Below the Farakka barrage the main stream enters Bangladesh as the Padma. IV. The basin covers more than a quarter of India's area.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. The Ganga basin covers about 26% of India's area and spans 11 States. The Bhagirathi–Hooghly branch carries water south to Kolkata while the Padma flows east.", "difficulty": "very-hard", "source": "UPSC Prelims · SSC CGL"},
  {"id": "geo-indian-rivers-115", "question": "Nashik, one of the four sites of the Kumbh Mela, stands on the bank of the river:", "options": ["Godavari", "Krishna", "Narmada", "Tapi"], "answer": 0, "explanation": "The Godavari rises at Trimbakeshwar close to Nashik and flows past the city. The Kumbh is held at Haridwar (Ganga), Prayagraj (Sangam), Ujjain (Shipra) and Nashik (Godavari).", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-116", "question": "Guwahati, the largest city of the north-east, lies on the bank of the:", "options": ["Barak", "Brahmaputra", "Teesta", "Subansiri"], "answer": 1, "explanation": "Guwahati sits on the south bank of the Brahmaputra. The Barak flows past Silchar in the Barak valley of southern Assam.", "difficulty": "easy", "source": "SSC CHSL · RRB NTPC"},
  {"id": "geo-indian-rivers-117", "question": "The Teesta, whose water sharing is a long-pending issue with Bangladesh, flows through which Indian states before entering Bangladesh?", "options": ["Assam and Meghalaya", "Bihar and West Bengal", "Sikkim and West Bengal", "Arunachal Pradesh and Assam"], "answer": 2, "explanation": "The Teesta rises in north Sikkim, flows past the Darjeeling hills into the plains of north Bengal and then joins the Brahmaputra (Jamuna) in Bangladesh.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "geo-indian-rivers-118", "question": "The Sabarmati, on which Ahmedabad stands, rises in the:", "options": ["Satpura range of Madhya Pradesh", "Western Ghats near Nashik", "Saurashtra plateau", "Aravalli hills of Rajasthan"], "answer": 3, "explanation": "The Sabarmati rises in the Aravallis in Udaipur district, Rajasthan, and flows south-west across Gujarat into the Gulf of Khambhat.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "geo-indian-rivers-119", "question": "The Mullaperiyar dam, which lies in Kerala but is operated by Tamil Nadu under a lease from the colonial period, is built on the:", "options": ["Periyar", "Kaveri", "Vaigai", "Bharathapuzha"], "answer": 0, "explanation": "Mullaperiyar (1895) is on the Periyar in Idukki district; its water is diverted east through a tunnel into the Vaigai basin of Tamil Nadu, which is the root of the inter-state dispute.", "difficulty": "moderate", "source": "State PSC · SSC CGL"},
  {"id": "geo-indian-rivers-120", "question": "Majuli, a large inhabited river island known for its Vaishnava satras, lies in the river:", "options": ["Ganga", "Brahmaputra", "Godavari", "Mahanadi"], "answer": 1, "explanation": "Majuli is in the Brahmaputra in upper Assam and became a district in 2016. Its area keeps shrinking because of bank erosion by the braided river.", "difficulty": "moderate", "source": "SSC CGL · State PSC"},
  {"id": "geo-indian-rivers-121", "question": "Which of these west-flowing rivers crosses the Tropic of Cancer twice?", "options": ["Narmada", "Tapi", "Mahi", "Luni"], "answer": 2, "explanation": "The Mahi rises in the Vindhyas of Madhya Pradesh, loops north into Rajasthan (Banswara) and turns back south-west through Gujarat, so it crosses the Tropic of Cancer twice before reaching the Gulf of Khambhat.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-122", "question": "The Pranhita, a major left-bank tributary of the Godavari, is formed by the union of the:", "options": ["Bhima and Tungabhadra", "Tawa and Hiran", "Manjira and Purna", "Wardha and Wainganga"], "answer": 3, "explanation": "The Wardha and the Wainganga meet in eastern Maharashtra to form the Pranhita, which joins the Godavari on the Telangana–Maharashtra border. Bhima and Tungabhadra are Krishna tributaries.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-123", "question": "The Wular lake, one of the largest freshwater lakes in India, is fed and drained by the:", "options": ["Jhelum", "Chenab", "Ravi", "Indus"], "answer": 0, "explanation": "The Jhelum flows into the Wular lake in Bandipora district and leaves it near Sopore, so the lake acts as a natural flood reservoir for the river.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-124", "question": "The Kolleru lake in Andhra Pradesh lies between the deltas of the:", "options": ["Mahanadi and Brahmani", "Godavari and Krishna", "Krishna and Penna", "Kaveri and Vaigai"], "answer": 1, "explanation": "Kolleru is a shallow freshwater lake between the Godavari and Krishna deltas. Chilika, a brackish lagoon, lies south of the Mahanadi delta in Odisha.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-125", "question": "The river that forms much of the boundary between Uttarakhand and Nepal is the:", "options": ["Gandak", "Kosi", "Kali (Mahakali)", "Bagmati"], "answer": 2, "explanation": "The Kali, called the Sharda further downstream, marks the western boundary of Nepal with Uttarakhand. The Gandak and Kosi flow out of Nepal into Bihar.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-126", "question": "The Chenab is formed in Himachal Pradesh by the confluence of the:", "options": ["Tunga and Bhadra", "Bhagirathi and Alaknanda", "Dihang and Lohit", "Chandra and Bhaga"], "answer": 3, "explanation": "The Chandra and the Bhaga meet at Tandi in Lahaul to form the Chandrabhaga, known as the Chenab as it flows into Jammu and Kashmir.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-127", "question": "Which of these rivers does NOT flow through a rift valley?", "options": ["Krishna", "Narmada", "Tapi", "Damodar"], "answer": 0, "explanation": "The Narmada and Tapi occupy rift troughs, and the Damodar flows through a rift that holds the Gondwana coal of Jharia and Raniganj. The Krishna flows across the plateau in a normal valley and builds a delta.", "difficulty": "hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-128", "question": "Match the tributary with its main river. A. Indravati  B. Bhavani  C. Tawa  D. Hasdeo; 1. Mahanadi  2. Narmada  3. Kaveri  4. Godavari", "options": ["A-4, B-2, C-3, D-1", "A-4, B-3, C-2, D-1", "A-1, B-3, C-2, D-4", "A-4, B-3, C-1, D-2"], "answer": 1, "explanation": "The Indravati joins the Godavari, the Bhavani the Kaveri (in Tamil Nadu), the Tawa the Narmada (Tawa reservoir in Madhya Pradesh), and the Hasdeo the Mahanadi in Chhattisgarh.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-129", "question": "Arrange these cities in the order a boat would pass them going down the Ganga: 1. Patna  2. Kanpur  3. Varanasi  4. Prayagraj", "options": ["2-3-4-1", "4-2-3-1", "2-4-3-1", "2-4-1-3"], "answer": 2, "explanation": "Downstream from Haridwar the Ganga passes Kanpur, then meets the Yamuna at Prayagraj, then flows past Varanasi and on to Patna in Bihar.", "difficulty": "very-hard", "source": "SSC CGL · State PSC"},
  {"id": "geo-indian-rivers-130", "question": "How many of these statements about the Krishna are correct? I. It rises near Mahabaleshwar in the Western Ghats. II. The Bhima and the Tungabhadra are among its tributaries. III. The Srisailam and Nagarjuna Sagar dams are built on it. IV. It enters the sea through an estuary without forming a delta.", "options": ["Only one", "Only two", "All four", "Only three"], "answer": 3, "explanation": "I, II and III are correct. The Krishna builds a large delta on the Andhra coast alongside the Godavari, so IV is wrong; estuaries are typical of the Narmada and Tapi.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-131", "question": "Assertion (A): Rivers of the Konkan and Malabar coasts are short and swift. Reason (R): The Western Ghats rise close to the west coast, leaving a narrow, steep slope down to the sea.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "With the watershed only 50–80 km from the sea, west-coast rivers drop steeply over a short course, forming falls such as Jog and having little room for deltas.", "difficulty": "very-hard", "source": "UPSC Prelims"},
  {"id": "geo-indian-rivers-132", "question": "How many of these pairs of river and the state where it rises are correct? I. Mahanadi — Chhattisgarh  II. Krishna — Maharashtra  III. Kaveri — Karnataka  IV. Tapi — Gujarat", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "I, II and III are correct (Sihawa, Mahabaleshwar and Talakaveri in Kodagu). The Tapi rises at Multai in Betul district of Madhya Pradesh and only reaches the sea in Gujarat, so IV is wrong.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-133", "question": "Match the dam with the river it is built on. A. Idukki  B. Srisailam  C. Ranjit Sagar  D. Gandhi Sagar; 1. Ravi  2. Chambal  3. Periyar  4. Krishna", "options": ["A-3, B-1, C-4, D-2", "A-2, B-4, C-1, D-3", "A-3, B-4, C-2, D-1", "A-3, B-4, C-1, D-2"], "answer": 3, "explanation": "Idukki's arch dam is on the Periyar in Kerala, Srisailam on the Krishna, Ranjit Sagar (Thein dam) on the Ravi at the Punjab–J&K border, and Gandhi Sagar on the Chambal in Madhya Pradesh.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
  {"id": "geo-indian-rivers-134", "question": "Assertion (A): The water of the Luni becomes saline in its lower course. Reason (R): It flows through an arid region where salt-bearing soils and high evaporation concentrate salts in the water.", "options": ["A is true but R is false", "Both A and R are true and R is the correct explanation of A", "A is false but R is true", "Both A and R are true but R is not the correct explanation of A"], "answer": 1, "explanation": "The Luni, also called Lavanavari (salt river), is fresh near Ajmer but turns brackish below Balotra as it crosses salty desert soils, and finally dies out in the Rann of Kutch.", "difficulty": "very-hard", "source": "UPSC Prelims · State PSC"},
];

export default questions;
